        function showUsageModal() {
            const modal = document.getElementById('usageModal');
            if (modal) {
                modal.style.display = 'flex';
                loadUsageStats();
            }
        }

        async function loadUsageStats() {
            try {
                const resp = await fetch('/api/admin/subscription-usage');
                const data = await resp.json();
                if (data.success) {
                    const stats = data.stats;
                    const container = document.getElementById('usageStatsContent');
                    if (container) {
                        container.innerHTML = `
                            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
                                <div style="background:rgba(255,255,255,0.05);padding:12px;border-radius:8px;">
                                    <div style="color:#888;font-size:11px;">${t('usage.today')}</div>
                                    <div style="font-size:20px;font-weight:700;color:#667eea;">${stats.today || 0}</div>
                                </div>
                                <div style="background:rgba(255,255,255,0.05);padding:12px;border-radius:8px;">
                                    <div style="color:#888;font-size:11px;">${t('usage.total')}</div>
                                    <div style="font-size:20px;font-weight:700;color:#764ba2;">${stats.total || 0}</div>
                                </div>
                            </div>
                            <div style="margin-top:12px;">
                                <div style="color:#888;font-size:11px;margin-bottom:6px;">${t('usage.last7days')}</div>
                                <div style="display:flex;gap:4px;align-items:flex-end;height:60px;">
                                    ${(stats.daily || []).map(d => {
                                        const max = Math.max(...(stats.daily || []).map(x => x.count), 1);
                                        const h = Math.max(4, (d.count / max) * 56);
                                        return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;">
                                            <div style="font-size:9px;color:#888;">${d.count}</div>
                                            <div style="width:100%;height:${h}px;background:linear-gradient(135deg,#667eea,#764ba2);border-radius:3px;"></div>
                                            <div style="font-size:9px;color:#666;">${d.day}</div>
                                        </div>`;
                                    }).join('')}
                                </div>
                            </div>
                        `;
                    }
                }
            } catch (e) {
                console.error('Failed to load usage stats:', e);
            }
        }

        function logout() {
            if (confirm(t('auth.logoutConfirm') || 'Выйти из админ панели?')) {
                localStorage.removeItem('aila_admin_token');
                localStorage.removeItem('aila_admin_auth');
                window.location.reload();
            }
        }
